sourcesContent:
import React, { useEffect, useState } from "react";
import { useParams, useNavigate, useLocation } from "react-router-dom";
import Sidebar from "../components/Sidebar";
import "../styles/Lesson.css";

export default function Lesson() {
  const { lessonId } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const { lesson } = location.state || {};

  const [tutors, setTutors] = useState([]);
  const [sessions, setSessions] = useState([]);
  const [selectedTutor, setSelectedTutor] = useState(null);
  const [signupProcessing, setSignupProcessing] = useState(false);
  const [bookingStatus, setBookingStatus] = useState(null);
  const [bookedSession, setBookedSession] = useState(null);
  const [watchedVideos, setWatchedVideos] = useState({});
  const [currentVideoPlayer, setCurrentVideoPlayer] = useState(null);
  const [activeStep, setActiveStep] = useState(1);
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(null);
  const [worksheet1Answers, setWorksheet1Answers] = useState({});
  const [worksheet2Answers, setWorksheet2Answers] = useState({});
  const [worksheet1Submitted, setWorksheet1Submitted] = useState(false);
  const [worksheet2Submitted, setWorksheet2Submitted] = useState(false);
  const [step3Completed, setStep3Completed] = useState(false);
  const [newQuestion, setNewQuestion] = useState("");
  const [newAnswer, setNewAnswer] = useState("");
  const [communityPosts, setCommunityPosts] = useState([
    {
      id: 1,
      author: "Alex Chen",
      type: "question",
      content: "Can someone explain the difference between mitosis and meiosis? I'm confused about when each process happens.",
      timestamp: "2 hours ago",
      replies: 5,
      likes: 12,
    },
    {
      id: 2,
      author: "Jordan Smith",
      type: "answer",
      content: "The scientific method is important because it provides a systematic approach to testing ideas and reducing bias in research. Each step helps ensure the results are reliable and reproducible.",
      timestamp: "1 hour ago",
      replies: 3,
      likes: 8,
    },
    {
      id: 3,
      author: "Maria Rodriguez",
      type: "question",
      content: "How does photosynthesis relate to cellular respiration? Are they opposite processes?",
      timestamp: "30 minutes ago",
      replies: 2,
      likes: 6,
    },
  ]);

  // Use videos from the lesson object if available, otherwise fallback to default Biology videos
  const defaultLessonVideos = [
    { id: 1, title: "Introduction to Biology", url: "https://www.youtube.com/watch?v=tZE_fQFK8EY&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=2" },
    { id: 2, title: "Scientific Method", url: "https://www.youtube.com/watch?v=xOLcZMw0hd4&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=3" },
    { id: 3, title: "What do Biologists Do?", url: "https://www.youtube.com/watch?v=rgZhDoPgzK8&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=4" },
    { id: 4, title: "Organized Life", url: "https://www.youtube.com/watch?v=cjR5zPrVjTc&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=5" },
    { id: 5, title: "Introduction to Ecology", url: "https://www.youtube.com/watch?v=aO3Yp45zmw8&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=6" },
  ];

  const lessonVideos = lesson?.videos || defaultLessonVideos;

  // Create detailed worksheets based on actual video content
  const createDetailedWorksheets = (videos, lessonTitle) => {
    const worksheetMap = {
      // Biology Lesson 1: Introduction to Biology
      "What is Biology?": [
        { id: 1, question: "What is the primary definition of biology?", options: ["The study of chemistry", "The scientific study of life and living organisms", "The study of fossils", "The study of rocks"], correct: 1 },
        { id: 2, question: "Which of the following is a characteristic of all living organisms?", options: ["They are stationary", "They are made of cells", "They never change", "They exist only on land"], correct: 1 },
        { id: 3, question: "What do all living things have in common?", options: ["Wings", "DNA and cells", "The ability to fly", "Fur or scales"], correct: 1 },
        { id: 4, question: "Biology is divided into how many main branches?", options: ["2", "3", "Many different branches", "Just one"], correct: 2 },
        { id: 5, question: "What is the smallest unit of life?", options: ["Atom", "Molecule", "Cell", "Organism"], correct: 2 },
        { id: 6, question: "Which biologists study microscopic organisms?", options: ["Ecologists", "Microbiologists", "Botanists", "Zoologists"], correct: 1 },
        { id: 7, question: "What is homeostasis?", options: ["A type of evolution", "An organism's ability to maintain stable internal conditions", "A disease", "A geographic location"], correct: 1 },
        { id: 8, question: "Do all organisms reproduce?", options: ["Only animals", "Only plants", "All living organisms reproduce", "Only some bacteria"], correct: 2 },
        { id: 9, question: "How do organisms respond to their environment?", options: ["They ignore it", "Through adaptation and behavior", "They cannot", "Only plants do"], correct: 1 },
        { id: 10, question: "What is the fundamental unit of organization in all living things?", options: ["Tissue", "Organ", "The cell", "System"], correct: 2 }
      ],
      "Scientific Method": [
        { id: 1, question: "What is the first step of the scientific method?", options: ["Hypothesis", "Observation", "Experimentation", "Conclusion"], correct: 1 },
        { id: 2, question: "What is a hypothesis?", options: ["A proven fact", "A testable prediction", "The final answer", "Random guessing"], correct: 1 },
        { id: 3, question: "What is a control group in an experiment?", options: ["The group receiving the treatment", "The group with no treatment for comparison", "Both groups combined", "Neither group"], correct: 1 },
        { id: 4, question: "Why is the scientific method important?", options: ["It's just tradition", "It ensures reliable and testable results", "It wastes time", "It prevents discovery"], correct: 1 },
        { id: 5, question: "What should all scientific experiments have?", options: ["Only one variable", "Multiple uncontrolled variables", "Variables that are controlled and one independent variable", "No variables"], correct: 2 },
        { id: 6, question: "What comes after collecting data?", options: ["Starting over", "Analyzing and drawing conclusions", "Publishing without analysis", "Ignoring the results"], correct: 1 },
        { id: 7, question: "Can a hypothesis be proven false?", options: ["No, never", "Yes, through experimentation", "Only sometimes", "It doesn't matter"], correct: 1 },
        { id: 8, question: "What is peer review?", options: ["Asking friends", "Other scientists checking your work", "Self-criticism only", "Not necessary"], correct: 1 },
        { id: 9, question: "How do scientists ensure accuracy?", options: ["By guessing", "By repeating experiments and collecting data carefully", "By avoiding documentation", "By trusting their intuition"], correct: 1 },
        { id: 10, question: "What is a theory in science?", options: ["Just an opinion", "A well-tested explanation supported by extensive evidence", "A guess", "Something that can't be tested"], correct: 1 }
      ],
      "What do Biologists Do?": [
        { id: 1, question: "What is a biologist's main role?", options: ["To create new chemicals", "To study living organisms and life processes", "To build machines", "To fix cars"], correct: 1 },
        { id: 2, question: "Which field involves studying animals?", options: ["Botany", "Zoology", "Geology", "Chemistry"], correct: 1 },
        { id: 3, question: "What is the study of plants called?", options: ["Zoology", "Botany", "Ecology", "Mycology"], correct: 1 },
        { id: 4, question: "What do marine biologists study?", options: ["Mountains", "Ocean ecosystems and organisms", "Deserts", "Space"], correct: 1 },
        { id: 5, question: "What is genetics the study of?", options: ["Rocks", "Heredity and genes", "Weather", "Stars"], correct: 1 },
        { id: 6, question: "Do biologists work only in laboratories?", options: ["Yes, always", "No, they work in labs, field sites, and other environments", "Only outdoors", "Only in hospitals"], correct: 1 },
        { id: 7, question: "What is a biologist's typical educational requirement?", options: ["High school diploma", "Bachelor's degree at minimum", "No education needed", "Only vocational training"], correct: 1 },
        { id: 8, question: "Which biologists study disease-causing organisms?", options: ["Botanists", "Microbiologists", "Ornithologists", "Entomologists"], correct: 1 },
        { id: 9, question: "What tools do biologists commonly use?", options: ["Only notebooks", "Microscopes, computers, and lab equipment", "Only cameras", "No tools needed"], correct: 1 },
        { id: 10, question: "Can biologists contribute to medicine?", options: ["No", "Yes, through research and understanding disease", "Only doctors can", "It's unrelated"], correct: 1 }
      ],
      "Organized Life": [
        { id: 1, question: "What is the basic unit of life?", options: ["Atom", "Molecule", "Cell", "Organ"], correct: 2 },
        { id: 2, question: "What is the correct order from smallest to largest living unit?", options: ["Cell→Tissue→Organ→Organism", "Organism→Organ→Tissue→Cell", "Tissue→Cell→Organ→Organism", "Organ→Cell→Tissue→Organism"], correct: 0 },
        { id: 3, question: "What is a tissue?", options: ["A single cell", "A group of similar cells working together", "An organ", "A complete organism"], correct: 1 },
        { id: 4, question: "What is an organ?", options: ["A single cell", "A tissue", "Two or more tissues working together to perform a function", "An entire system"], correct: 2 },
        { id: 5, question: "What is an organ system?", options: ["Organs that work independently", "Multiple organs working together to perform a function", "A single organ", "Just tissue"], correct: 1 },
        { id: 6, question: "Is organization important in living things?", options: ["No, organisms are random", "Yes, organization is essential for life", "Only in plants", "Only in animals"], correct: 1 },
        { id: 7, question: "What does the circulatory system do?", options: ["Digestion", "Transport of blood and nutrients", "Thinking", "Movement only"], correct: 1 },
        { id: 8, question: "How many systems does the human body have?", options: ["1", "2", "Multiple major systems (10+)", "Just one"], correct: 2 },
        { id: 9, question: "Can cells exist independently of tissues?", options: ["Never", "Yes, some cells function alone", "Only plant cells", "Only in organisms"], correct: 1 },
        { id: 10, question: "What is the hierarchy of life?", options: ["Random and non-specific", "Cell→Tissue→Organ→System→Organism", "Organism→System→Organ→Tissue→Cell", "No hierarchy exists"], correct: 1 }
      ],
      "Introduction to Ecology": [
        { id: 1, question: "What is ecology?", options: ["The study of rocks", "The study of organisms and their interactions with the environment", "The study of weather only", "The study of chemistry"], correct: 1 },
        { id: 2, question: "What is an ecosystem?", options: ["Just plants", "All organisms and the physical environment in an area", "Only animals", "Never changes"], correct: 1 },
        { id: 3, question: "What is a population?", options: ["All organisms on Earth", "All members of one species in an area", "Different species together", "Just humans"], correct: 1 },
        { id: 4, question: "What is a community in ecology?", options: ["A human town", "All populations of different species in an area", "Only predators", "Just one species"], correct: 1 },
        { id: 5, question: "What is a biome?", options: ["A small area", "A large geographical area with specific climate and organisms", "A single organism", "Just temperature"], correct: 1 },
        { id: 6, question: "Do organisms affect their environment?", options: ["No, they don't interact", "Yes, through various interactions", "Only some organisms", "Only humans do"], correct: 1 },
        { id: 7, question: "What are producers in an ecosystem?", options: ["Animals that hunt", "Plants and organisms that make their own food", "Animals only", "Decomposers"], correct: 1 },
        { id: 8, question: "What are consumers in an ecosystem?", options: ["Organisms that make their own food", "Organisms that eat other organisms", "Only herbivores", "Only plants"], correct: 1 },
        { id: 9, question: "What is biodiversity?", options: ["The number of humans", "The variety of different species and genes in an area", "Only plant variety", "Never important"], correct: 1 },
        { id: 10, question: "Why is ecology important?", options: ["It's not useful", "Understanding ecosystems helps us protect the environment", "Only for scientists", "It has no practical application"], correct: 1 }
      ],
      // Biology Lesson 2: Ecology
      "Community Ecology": [
        { id: 1, question: "What is community ecology?", options: ["Only studying human communities", "The study of how different species interact in a shared environment", "The study of just one species", "Urban planning"], correct: 1 },
        { id: 2, question: "What is competition in an ecosystem?", options: ["Friendly cooperation", "Organisms struggling for the same resources", "Predation", "Decomposition"], correct: 1 },
        { id: 3, question: "What is predation?", options: ["Competition for food", "One organism eating another", "Mutual benefit", "Decomposition"], correct: 1 },
        { id: 4, question: "What is mutualism?", options: ["One organism benefits", "Both organisms benefit from the relationship", "One is harmed", "Neither is affected"], correct: 1 },
        { id: 5, question: "What is parasitism?", options: ["Mutual benefit", "One organism benefits while the other is harmed", "Both are harmed", "Neither is affected"], correct: 1 },
        { id: 6, question: "What determines species composition in a community?", options: ["Random factors only", "Physical environment, competition, and predation", "Just luck", "Only temperature"], correct: 1 },
        { id: 7, question: "What is a food chain?", options: ["Stores selling food", "A sequence showing how energy flows from organism to organism", "Just plants", "Only animals"], correct: 1 },
        { id: 8, question: "What is the role of decomposers?", options: ["Creating food", "Breaking down dead matter and recycling nutrients", "Predation", "Fixing nitrogen"], correct: 1 },
        { id: 9, question: "Can two species occupy the same niche?", options: ["Always", "Generally not, they'll compete until one is excluded", "Only in water", "Only on land"], correct: 1 },
        { id: 10, question: "What increases biodiversity in a community?", options: ["Removing all organisms", "Having diverse habitats and reduced competition", "Pollution", "Monocultures"], correct: 1 }
      ],
      "Population Ecology": [
        { id: 1, question: "What is population ecology?", options: ["Study of human cities", "The study of populations and their dynamics", "Study of single organisms", "Study of behavior only"], correct: 1 },
        { id: 2, question: "What is population growth?", options: ["Individuals getting larger", "Increase in the number of individuals over time", "Only reproduction", "Migration only"], correct: 1 },
        { id: 3, question: "What is the carrying capacity?", options: ["What an organism can carry", "The maximum population size an environment can support", "Birth rate", "Immigration rate"], correct: 1 },
        { id: 4, question: "What happens when a population exceeds carrying capacity?", options: ["It keeps growing", "The population declines due to resource scarcity", "Nothing changes", "It doubles"], correct: 1 },
        { id: 5, question: "What is birth rate?", options: ["The age of organisms", "The number of new individuals born per unit time", "Death of organisms", "Movement"], correct: 1 },
        { id: 6, question: "What is death rate?", options: ["Birth of organisms", "The number of organisms dying per unit time", "Population growth", "Immigration"], correct: 1 },
        { id: 7, question: "What is immigration?", options: ["Leaving a population", "Movement into a population", "Death", "Birth"], correct: 1 },
        { id: 8, question: "What factors limit population growth?", options: ["None, unlimited growth", "Food, space, disease, predation", "Only food", "Only predators"], correct: 1 },
        { id: 9, question: "What is logistic growth?", options: ["Exponential forever", "Growth that slows as carrying capacity is reached", "No growth", "Decline only"], correct: 1 },
        { id: 10, question: "How do density-dependent factors affect populations?", options: ["Never affect them", "Their effect increases with population density", "Always decrease populations", "Only in forests"], correct: 1 }
      ],
      "What is Climate Change?": [
        { id: 1, question: "What is climate change?", options: ["Weather getting warmer for one day", "Long-term shifts in global temperature and weather patterns", "Not happening", "Only seasonal variation"], correct: 1 },
        { id: 2, question: "What is the greenhouse effect?", options: ["Effect of plant growth", "Trapping of heat by atmospheric gases leading to warming", "Cooling the planet", "Only happens at night"], correct: 1 },
        { id: 3, question: "Which gas is primarily responsible for climate change?", options: ["Oxygen", "Nitrogen", "Carbon dioxide", "Helium"], correct: 2 },
        { id: 4, question: "What is the main human cause of climate change?", options: ["Animal breathing", "Burning of fossil fuels", "Plant growth", "Ocean waves"], correct: 1 },
        { id: 5, question: "Is climate change natural?", options: ["Entirely natural", "Primarily caused by human activities", "Doesn't exist", "Only happens in deserts"], correct: 1 },
        { id: 6, question: "What is the difference between climate and weather?", options: ["They're the same", "Climate is long-term patterns, weather is short-term", "Weather is more important", "No difference"], correct: 1 },
        { id: 7, question: "What evidence shows climate is changing?", options: ["Just computer models", "Rising temperatures, melting ice, sea level rise", "No evidence", "Only in cities"], correct: 1 },
        { id: 8, question: "Can we slow climate change?", options: ["No, it's inevitable", "Yes, through reducing emissions and conservation", "It will stop on its own", "Only governments can"], correct: 1 },
        { id: 9, question: "What is a carbon footprint?", options: ["A footprint on carbon", "The total greenhouse gases produced by an activity", "Size of feet", "Only factories have them"], correct: 1 },
        { id: 10, question: "What year did the Paris Climate Accord occur?", options: ["2000", "2010", "2015", "2025"], correct: 2 }
      ],
      "The Effects of Climate Change": [
        { id: 1, question: "What is a major effect of climate change on ecosystems?", options: ["No changes", "Species extinction, habitat loss, ecosystem disruption", "Ecosystem improvement", "Only affects humans"], correct: 1 },
        { id: 2, question: "How does climate change affect sea levels?", options: ["Levels stay constant", "Warming causes ice melt and water expansion, raising levels", "Levels decrease", "No effect"], correct: 1 },
        { id: 3, question: "What happens to coral reefs with warming oceans?", options: ["They grow faster", "Bleaching occurs, threatening the ecosystem", "No effect", "They become stronger"], correct: 1 },
        { id: 4, question: "How does climate change affect agriculture?", options: ["Increases all crops", "Alters growing seasons and threatens food security", "No effect on farming", "Only helps farming"], correct: 1 },
        { id: 5, question: "What is ocean acidification?", options: ["Oceans becoming salty", "Increased CO2 absorption making oceans more acidic", "Oceans becoming basic", "Not happening"], correct: 1 },
        { id: 6, question: "Which species are most threatened by climate change?", options: ["Only large animals", "Species in extreme habitats like polar and mountain regions", "Introduced species only", "No species affected"], correct: 1 },
        { id: 7, question: "How does climate change affect human health?", options: ["No effects", "Through heat stress, disease vectors, and food security", "Only positive effects", "Not related"], correct: 1 },
        { id: 8, question: "What are tipping points in climate?", options: ["Points where nothing changes", "Critical thresholds where change accelerates drastically", "The coldest points", "Only in ice ages"], correct: 1 },
        { id: 9, question: "Can extreme weather be linked to climate change?", options: ["Never", "Yes, warming increases frequency of extreme events", "Only in summer", "Only in winter"], correct: 1 },
        { id: 10, question: "What is climate migration?", options: ["Seasonal animal movement", "Movement of people due to climate impacts", "Tourism only", "Not occurring"], correct: 1 }
      ],
      "Conservation Biology": [
        { id: 1, question: "What is conservation biology?", options: ["Preserving buildings", "The science of protecting biodiversity and ecosystems", "Only protecting animals", "Not a real science"], correct: 1 },
        { id: 2, question: "What is habitat loss?", options: ["Animals losing weight", "Destruction of natural habitats threatening species", "Not a problem", "Only in cities"], correct: 1 },
        { id: 3, question: "What is extinction?", options: ["Species moving to new areas", "Permanent loss of a species", "Animals changing appearance", "Not a natural process"], correct: 1 },
        { id: 4, question: "What are invasive species?", options: ["Native species", "Non-native species that harm ecosystems", "Always harmless", "Improve biodiversity"], correct: 1 },
        { id: 5, question: "Why is biodiversity important?", options: ["It's not important", "It provides ecosystem services and resilience", "Only for beauty", "Only for science"], correct: 1 },
        { id: 6, question: "What is a protected area?", options: ["Private property", "Land designated to protect biodiversity and ecosystems", "Only national parks", "Zoos only"], correct: 1 },
        { id: 7, question: "What is sustainable use?", options: ["Using more resources", "Using resources without depleting them for future", "No conservation needed", "Only for plants"], correct: 1 },
        { id: 8, question: "Can humans and conservation coexist?", options: ["No, never", "Yes, through sustainable practices and protection", "Humans must leave", "Conservation is pointless"], correct: 1 },
        { id: 9, question: "What is reforestation?", options: ["Cutting down forests", "Planting trees to restore forests", "Only a theory", "Harms the environment"], correct: 1 },
        { id: 10, question: "What is the role of zoos in conservation?", options: ["No role", "Breeding programs and education for endangered species", "Only entertainment", "Harmful to animals"], correct: 1 }
      ]
    };

    // Fallback for any lesson not in the map
    if (!worksheetMap[videos?.[0]?.title] && videos?.length > 0) {
      return Array.from({ length: 10 }, (_, i) => ({
        id: i + 1,
        question: `What is the main topic of "${videos[i % videos.length]?.title}"?`,
        options: ["Option A", "Option B", "Option C", "Option D"],
        correct: 0
      }));
    }

    return worksheetMap[videos?.[0]?.title] || [];
  };

  const worksheet1Questions = createDetailedWorksheets(lessonVideos, lesson?.title || "");
  // Worksheet 2 with different angle on the same content
  const createSecondWorksheet = (videos, lessonTitle) => {
    const secondSheetMap = {
      "What is Biology?": [
        { id: 1, question: "How many levels of biological organization are there?", options: ["3", "4", "Many levels from atoms to organisms", "Just two"], correct: 2 },
        { id: 2, question: "What is an adaptation?", options: ["A disease", "A trait that helps an organism survive", "A behavior change", "None of these"], correct: 1 },
        { id: 3, question: "Do unicellular organisms have organelles?", options: ["All do", "Prokaryotes don't, eukaryotes do", "None do", "Plants only"], correct: 1 },
        { id: 4, question: "What does 'evolution' mean in biology?", options: ["Change in fashion", "Change in genetic composition of populations over time", "Individual growth", "Extinction"], correct: 1 },
        { id: 5, question: "What is ecology focused on?", options: ["Individual organisms only", "Interactions between organisms and their environment", "Dead organisms", "Chemical reactions"], correct: 1 },
        { id: 6, question: "What unites all living things?", options: ["They all move", "They all have cells, DNA, and use energy", "They all have brains", "They're all plants"], correct: 1 },
        { id: 7, question: "What is an example of biological diversity?", options: ["All humans are the same", "Variety of species from bacteria to whales", "All animals look alike", "No diversity exists"], correct: 1 },
        { id: 8, question: "How do organisms maintain homeostasis?", options: ["They don't need to", "Through internal regulation mechanisms", "Only in winter", "Never"], correct: 1 },
        { id: 9, question: "What percentage of living things are insects?", options: ["10%", "25%", "Over 50% of known species", "Less than 5%"], correct: 2 },
        { id: 10, question: "What is the most recently evolved form of life?", options: ["Bacteria", "Fish", "Mammals including humans", "Plants"], correct: 2 }
      ],
      "Scientific Method": [
        { id: 1, question: "How many steps are in the scientific method?", options: ["3", "4", "5-6 main steps", "2"], correct: 2 },
        { id: 2, question: "What is independent variable?", options: ["The variable that doesn't change", "The variable the scientist changes on purpose", "The outcome measured", "Always temperature"], correct: 1 },
        { id: 3, question: "What is a dependent variable?", options: ["The variable being changed", "The variable measured as a result", "The control group", "The hypothesis"], correct: 1 },
        { id: 4, question: "Why are repeated trials important?", options: ["They waste time", "They increase reliability and reduce error", "They're not important", "Only required sometimes"], correct: 1 },
        { id: 5, question: "Can scientists disprove a hypothesis?", options: ["Never", "Yes, through experimentation", "Only sometimes", "Hypotheses can't be tested"], correct: 1 },
        { id: 6, question: "What is a confounding variable?", options: ["A helpful variable", "A variable affecting results but not the one being studied", "The same as control", "Not important"], correct: 1 },
        { id: 7, question: "Should experiments be reproducible?", options: ["No, each test is unique", "Yes, results should be consistent", "Only sometimes", "Not necessary"], correct: 1 },
        { id: 8, question: "What happens if data contradicts your hypothesis?", options: ["Reject the data", "Analyze why and revise understanding", "Stop the experiment", "Lie about results"], correct: 1 },
        { id: 9, question: "How do scientists share findings?", options: ["Keep them secret", "Publish in journals and conferences", "Only tell friends", "Never share"], correct: 1 },
        { id: 10, question: "What is the purpose of a literature review?", options: ["Reading fiction", "Researching what's already known on the topic", "Not necessary", "Writing the conclusion"], correct: 1 }
      ],
      "What do Biologists Do?": [
        { id: 1, question: "What is molecular biology?", options: ["Biology of molecules like DNA and proteins", "Study of moles", "Only in chemistry", "Not a real field"], correct: 0 },
        { id: 2, question: "What do cellular biologists study?", options: ["Organisms only", "Structure and function of cells", "Only bacteria", "Only animals"], correct: 1 },
        { id: 3, question: "What is developmental biology?", options: ["Building things", "How organisms grow and develop from embryo to adult", "Psychology", "Only in humans"], correct: 1 },
        { id: 4, question: "What is an evolutionary biologist?", options: ["Studies evolution and adaptation", "Designs tools", "Only fossil expert", "Studies weather"], correct: 0 },
        { id: 5, question: "What specialization studies human biology?", options: ["Ornithology", "Human anatomy and physiology", "Entomology", "Mycology"], correct: 1 },
        { id: 6, question: "Where do field biologists work?", options: ["Only labs", "In natural habitats collecting data", "Only in museums", "Never outdoors"], correct: 1 },
        { id: 7, question: "What technologies do modern biologists use?", options: ["No technology", "Electron microscopes, genetic sequencers, computers", "Just magnifying glasses", "Only cameras"], correct: 1 },
        { id: 8, question: "Can biologists work in industry?", options: ["Never", "Yes, pharmaceutical and biotechnology companies", "Only government", "Only universities"], correct: 1 },
        { id: 9, question: "What is bioinformatics?", options: ["Study of facts", "Using computers to analyze biological data", "Only for bacteria", "Not used in biology"], correct: 1 },
        { id: 10, question: "How important is math to biology?", options: ["Not at all", "Very important for statistics and modeling", "Only for physicists", "Unnecessary"], correct: 1 }
      ],
      "Organized Life": [
        { id: 1, question: "What are the levels of organization in order?", options: ["Random", "Atom→Molecule→Organelle→Cell→Tissue→Organ→System→Organism", "Organism→System→Cell→Tissue", "Just cells"], correct: 1 },
